(async()=>{
 const masterFile=fs.readFileSync(path.join(__dirname,'1-two-to-one-master.png'));
 const {data:master,info}=await sharp(masterFile).removeAlpha().raw().toBuffer({resolveWithObject:true});
 const reports=[];
 for(const [inputName,outputName] of [['2-mid-front-candidate.png','2-mid-fixed-contacts.png'],['3-ankle-joined.png','3-full-fixed-contacts.png']]){
  const input=fs.readFileSync(path.join(__dirname,inputName));
  const raw=await sharp(input).removeAlpha().raw().toBuffer(),out=Buffer.from(raw);
  // Previously authorized exact-copy repair of planted shoes and unobstructed mat only.
  const rect=[565,inputName==='3-ankle-joined.png'?900:844,1415,966];let changed=0,outside=0;
  for(let y=rect[1];y<rect[3];y++)for(let x=rect[0];x<rect[2];x++){
   const p=(y*info.width+x)*3;
   if(!raw.subarray(p,p+3).equals(master.subarray(p,p+3)))changed++;
   master.copy(out,p,p,p+3);
  }
  for(let y=0;y<info.height;y++)for(let x=0;x<info.width;x++){
   if(x>=rect[0]&&x<rect[2]&&y>=rect[1]&&y<rect[3])continue;
   const p=(y*info.width+x)*3;if(!raw.subarray(p,p+3).equals(out.subarray(p,p+3)))outside++;
  }
  if(outside)throw Error('Outside fixed-contact rectangle changed');
  await sharp(out,{raw:{width:info.width,height:info.height,channels:3}}).png().toFile(path.join(__dirname,outputName));
  reports.push({inputName,outputName,rect,changedPixels:changed,changedOutsideRect:outside,masterSha256:hash(masterFile),inputSha256:hash(input),outputSha256:hash(fs.readFileSync(path.join(__dirname,outputName)))});
 }
 fs.writeFileSync(path.join(__dirname,'fixed-contacts-provenance.json'),JSON.stringify({method:'User-approved exact source copy of stationary shoes and unobstructed mat. Mid copy starts y844; full copy starts y900 preserving the imagegen-repaired ankle and shoe collar. No moving anatomy or equipment repair.',reports},null,2)+'\n');console.log(reports);
})();

