const upper={x:359,y:63,r:28},anchor={x:279,y:46},lower={x:282,y:540,r:25};
function geometry(y,end){
 const dx=upper.x-lower.x,dy=upper.y-y,d=Math.hypot(dx,dy),n=Math.atan2(dy,dx)+Math.acos((lower.r+upper.r)/d);
 const ad=Math.hypot(anchor.x-lower.x,anchor.y-y),a=Math.atan2(anchor.y-y,anchor.x-lower.x)-Math.acos(lower.r/ad);
 const ed=Math.hypot(end[0]-upper.x,end[1]-upper.y),e=Math.atan2(end[1]-upper.y,end[0]-upper.x)-Math.acos(upper.r/ed);
 const leftAngle=(a+2*Math.PI)%(2*Math.PI),exit=(e+2*Math.PI)%(2*Math.PI),incoming=n+Math.PI;
 const length=Math.sqrt(ad*ad-lower.r**2)+(leftAngle-n)*lower.r+Math.sqrt(d*d-(lower.r+upper.r)**2)+(exit-incoming)*upper.r+Math.sqrt(ed*ed-upper.r**2);
 return {y,length,left:[lower.x+lower.r*Math.cos(a),y+lower.r*Math.sin(a)],right:[lower.x+lower.r*Math.cos(n),y+lower.r*Math.sin(n)],upper:[upper.x-upper.r*Math.cos(n),upper.y-upper.r*Math.sin(n)]};
}
(async()=>{
 const masterFile=fs.readFileSync(path.join(__dirname,'1-two-to-one-master.png'));
 const {data:master,info}=await sharp(masterFile).removeAlpha().raw().toBuffer({resolveWithObject:true});
 const baseline=geometry(540,[610,114]).length,records=[];
 const inputs=[['1-two-to-one-master.png','1-equipment-fixed.png',[610,114]],['2-mid-fixed-contacts.png','2-equipment-fixed.png',[918,304]],['3-full-fixed-contacts.png','3-equipment-fixed.png',[1125,514]]];
 for(const [inputName,outputName,end] of inputs){
  const input=fs.readFileSync(path.join(__dirname,inputName)),raw=await sharp(input).removeAlpha().raw().toBuffer(),out=Buffer.from(raw);
  let lo=130,hi=540;for(let i=0;i<60;i++){const m=(lo+hi)/2;if(geometry(m,end).length>baseline)hi=m;else lo=m;}
  const rise=Math.round(540-(lo+hi)/2),g=geometry(540-rise,end);
  const copy=(src,x0,y0,x1,y1,dy=0)=>{for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const s=(y*info.width+x)*3,t=((y+dy)*info.width+x)*3;src.copy(out,t,s,s+3);}};
  // Exact frozen stationary machine; preserve each pose's existing outgoing cable near top outlet.
