   if(y>34&&y<110&&x>350)continue;
   const p=(y*info.width+x)*3;master.copy(out,p,p,p+3);
  }
  const clear=(x0,y0,x1,y1)=>{for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const p=(y*info.width+x)*3;out[p]=out[p+1]=out[p+2]=0;}};
  clear(252,54,331,614);clear(247,510,312,616);clear(208,614,364,639);
  // Guides pass behind moving assembly. Restore clean original source strips where old plate occluded them.
  copy(master,232,54,250,614);copy(master,325,54,341,614);
  for(let y=614;y<639;y++)for(let x=208;x<364;x++){const s=(450*info.width+x)*3,t=(y*info.width+x)*3;master.copy(out,t,s,s+3);}
  clear(252,614,325,639);
  // Authorized rigid source-pixel assembly translation; no scale or rotation.
  for(const rect of [[248,513,311,567],[264,566,299,615],[208,614,364,639]])copy(master,...rect,-rise);
  const svg=`<svg width="1536" height="1024" xmlns="http://www.w3.org/2000/svg"><path d="M279 49 L${g.left.join(' ')} A25 25 0 0 0 ${g.right.join(' ')} L${g.upper.join(' ')}" fill="none" stroke="#787878" stroke-width="2.8"/><path d="M279 49 L${g.left.join(' ')} A25 25 0 0 0 ${g.right.join(' ')} L${g.upper.join(' ')}" fill="none" stroke="#bababa" stroke-width="1"/></svg>`;
  const withCable=await sharp(out,{raw:{width:info.width,height:info.height,channels:3}}).composite([{input:Buffer.from(svg)}]).removeAlpha().raw().toBuffer();withCable.copy(out);
  let changed=0,outside=0,athlete=0;for(let y=0;y<info.height;y++)for(let x=0;x<info.width;x++){const p=(y*info.width+x)*3;if(!raw.subarray(p,p+3).equals(out.subarray(p,p+3))){changed++;if(x<80||x>=475)outside++;if(x>=500)athlete++;}}
  if(outside||athlete)throw Error('Equipment repair changed outside machine');
  await sharp(out,{raw:{width:info.width,height:info.height,channels:3}}).png().toFile(path.join(__dirname,outputName));
  records.push({inputName,outputName,end,rise,geometry:g,baselineLength:baseline,lengthError:g.length-baseline,changedPixels:changed,changedOutsideMachine:outside,changedAthletePixels:athlete,inputSha256:hash(input),outputSha256:hash(fs.readFileSync(path.join(__dirname,outputName)))});
 }
 fs.writeFileSync(path.join(__dirname,'equipment-repair-provenance.json'),JSON.stringify({authorization:'User explicitly approved woodchopper rigid plate/pulley translation and cable reconnection on29September2026.',method:'Exact master stationary machine restoration and rigid integer assembly translation. Thin internal cable redrawn along planar tangent geometry. Outgoing cable and athlete unchanged. Geometry is a planar diagnostic, not calibrated biomechanics.',masterSha256:hash(masterFile),records},null,2)+'\n');console.log(records);
})();

